const cfg = $json;
if (!cfg.telegramChatId) {
  throw new Error('Config.telegramChatId is still 0 — set it to your chat id (pnpm telegram:get-chat-id in the parent repo).');
}

// The watermark. In the agent this is agent.db memory (set_memory
// 'news_digest.last_read_at'); here it is n8n's own per-workflow static data,
// which n8n persists between PRODUCTION executions (manual runs do not save it).
const store = $getWorkflowStaticData('global');
const nowISO = new Date().toISOString();
const sinceISO =
  store.newsDigestLastReadAt ||
  new Date(Date.now() - cfg.bootstrapHours * 3600 * 1000).toISOString();

const call = (label, tool, args) => ({
  json: {
    label,
    tool,
    argsJson: JSON.stringify(args),
    mcpUrl: cfg.mcpUrl,
    sinceISO,
    nowISO,
  },
});

// One batch, one MCP session. 'posts' is the digest window; 'history' is the
// dedup corpus; the two skills are the system prompt the agent runs, read from
// the same files the supervisor reads — so the digest cannot drift from the
// agent's own instructions.
return [
  call('posts', 'list_news', { source: 'channel', sinceISO, limit: cfg.postLimit }),
  call('history', 'get_telegram_chat_history', { chatId: cfg.telegramChatId, limit: cfg.historyLimit }),
  call('skill:composer', 'read_skill', { fileName: cfg.composerSkill }),
  call('skill:digest', 'read_skill', { fileName: cfg.digestSkill }),
];

const cfg = $('Config').first().json;

const byLabel = {};
for (const item of $input.all()) byLabel[item.json.label] = item.json.result;

const posts = (byLabel.posts && byLabel.posts.items) || [];
const history = (byLabel.history && byLabel.history.messages) || [];

const skillText = (entry, fileName) => {
  if (!entry || entry.found !== true) throw new Error('read_skill could not find ' + fileName);
  return entry.effectiveInstructions;
};
// Same layering as the agent's compose step: the always-on composer rules
// first (stable prefix, prompt-cache friendly), the domain skill on top.
const systemPrompt = [
  skillText(byLabel['skill:composer'], cfg.composerSkill),
  skillText(byLabel['skill:digest'], cfg.digestSkill),
].join('\n\n');

const historyJson = JSON.stringify(history, null, 2);

// The agent asks MCP for a fixed chunk count (list_news chunks:3) because its
// plan DSL can only reference ${bind.chunks.0}, ${bind.chunks.1}, … statically.
// n8n has real iteration, so chunk here instead — by character budget, which
// keeps one map call's context flat whether the window holds 40 posts or 900.
// Contiguous, never round-robin: list_news is time-ordered, so neighbours are
// the posts most likely to describe the same event and to consolidate locally.
const budget = cfg.maxCharsPerChunk;
const chunks = [];
let current = [];
let currentChars = 0;
for (const post of posts) {
  // Measured the way the prompt renders it (pretty JSON), so the budget is
  // the real prompt size and not a compact-JSON underestimate.
  const size = JSON.stringify(post, null, 2).length;
  if (current.length > 0 && currentChars + size > budget) {
    chunks.push(current);
    current = [];
    currentChars = 0;
  }
  current.push(post);
  currentChars += size;
}
// Always emit at least one chunk: an empty window must still reach the reduce
// step, which is what produces the "тихий день" message.
chunks.push(current);

return chunks.map((chunk, index) => ({
  json: {
    chunkIndex: index,
    chunkCount: chunks.length,
    postCount: chunk.length,
    postsJson: JSON.stringify(chunk, null, 2),
    historyJson,
    systemPrompt,
  },
}));

// Every map item is one selection array. The map LLM was told to answer with a
// JSON array; parse it the same lenient way the agent's executor binds a
// compose result — non-JSON stays a string and the reduce step sees it verbatim
// instead of the run dying here.
const selections = $input.all().map((item) => {
  const raw = (item.json.text || '').trim();
  const cleaned = raw.replace(/^```(?:json)?/i, '').replace(/```$/, '').trim();
  try {
    return JSON.parse(cleaned);
  } catch {
    return cleaned;
  }
});

const first = $('Chunk posts').first().json;
return [
  {
    json: {
      systemPrompt: first.systemPrompt,
      historyJson: first.historyJson,
      selectionsJson: JSON.stringify(selections, null, 2),
      nowISO: $('Window + MCP calls').first().json.nowISO,
      chunkCount: selections.length,
    },
  },
];

