const cfg = $('Config').first().json;
const digest = ($json.text || '').trim();

return [
  {
    json: {
      label: 'sent',
      tool: 'send_telegram_message',
      argsJson: JSON.stringify({ chatId: cfg.telegramChatId, text: digest }),
      mcpUrl: cfg.mcpUrl,
    },
  },
];

const sent = $input.first().json.result;
if (!sent || sent.delivered !== true) {
  throw new Error('send_telegram_message did not confirm delivery: ' + JSON.stringify(sent).slice(0, 300));
}

// Advance the watermark only after a confirmed delivery — exactly the agent's
// rule ("only after a successful full news-digest delivery"). A failed send
// leaves the window open, so the next run re-reads the same posts.
const store = $getWorkflowStaticData('global');
store.newsDigestLastReadAt = $('Window + MCP calls').first().json.nowISO;

return [
  {
    json: {
      delivered: true,
      chatId: sent.chatId,
      messageId: sent.messageId,
      watermark: store.newsDigestLastReadAt,
      chunks: $('Prepare reduce input').first().json.chunkCount,
    },
  },
];
